#include <iostream>

int main() {
    // Target secret number (deterministic simulation of rand() % 101)
    const int number = 39;
    std::cout << "Guess a magic number between 0 and 100\n";

    // Critical initialization: choose a sentinel outside [0, 100]
    int guess = -1;

    while (guess != number) {
        std::cout << "Enter your guess: ";
        if (!(std::cin >> guess)) {
            break; // Stop safely on EOF
        }

        if (guess == number) {
            std::cout << "Yes, the number is " << number << "\n";
        } else if (guess > number) {
            std::cout << "Your guess is too high\n";
        } else {
            std::cout << "Your guess is too low\n";
        }
    }

    return 0;
}
